"""Original 0.9 laboratory artwork and equipment models, reproducible with Pillow."""
from pathlib import Path
from PIL import Image,ImageDraw,ImageFont
import json,copy
root=Path(__file__).resolve().parents[1]/'src/main/resources'
a=root/'assets/prscraft';font=ImageFont.load_default(size=7)
def write(path,data):path.parent.mkdir(parents=True,exist_ok=True);path.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
for name,base,centre in [('digital_modem','amplifier','quartz'),('packet_sender','message_codec','comparator'),('packet_receiver','message_receiver','observer'),('orthogonality_meter','correlator','amethyst_shard')]:
 model=json.loads((a/f'models/block/{base}.json').read_text());text=json.dumps(model).replace(base+'_panel',name+'_panel').replace(base+'_top',name+'_top');write(a/f'models/block/{name}.json',json.loads(text));states=json.loads((a/f'blockstates/{base}.json').read_text());states=json.loads(json.dumps(states).replace('block/'+base,'block/'+name));write(a/f'blockstates/{name}.json',states);write(a/f'models/item/{name}.json',{'parent':'prscraft:block/'+name})
 loot=json.loads((root/'data/prscraft/loot_table/blocks/amplifier.json').read_text());write(root/f'data/prscraft/loot_table/blocks/{name}.json',json.loads(json.dumps(loot).replace('prscraft:amplifier','prscraft:'+name)))
 write(root/f'data/prscraft/recipe/{name}.json',{'type':'minecraft:crafting_shaped','pattern':['IRI','RCR','IGI'],'key':{'I':{'item':'minecraft:iron_ingot'},'R':{'item':'minecraft:redstone'},'C':{'item':'minecraft:'+centre},'G':{'item':'minecraft:glass'}},'result':{'id':'prscraft:'+name}})
faces={k:{'texture':'#case'} for k in ['north','south','west','east','up','down']};faces['north']={'texture':'#panel','uv':[0,0,16,16]};faces['up']={'texture':'#top'}
model={'parent':'minecraft:block/block','textures':{'case':'prscraft:block/instrument_case','panel':'prscraft:block/simulator_panel','top':'prscraft:block/simulator_top','particle':'prscraft:block/instrument_case'},'elements':[{'from':[1,0,2],'to':[15,11,14],'faces':faces}]};write(a/'models/block/simulator.json',model);write(a/'models/item/simulator.json',{'parent':'prscraft:block/simulator'});write(a/'blockstates/simulator.json',{'variants':{'facing='+d:{'model':'prscraft:block/simulator','y':rot} for d,rot in [('north',0),('east',90),('south',180),('west',270)]}})
loot=json.loads((root/'data/prscraft/loot_table/blocks/drawing_board.json').read_text());write(root/'data/prscraft/loot_table/blocks/simulator.json',json.loads(json.dumps(loot).replace('prscraft:drawing_board','prscraft:simulator')))
write(root/'data/prscraft/recipe/simulator.json',{'type':'minecraft:crafting_shaped','pattern':['IGI','RCR','IBI'],'key':{'I':{'item':'minecraft:iron_ingot'},'R':{'item':'minecraft:redstone'},'C':{'item':'minecraft:comparator'},'G':{'item':'minecraft:glass'},'B':{'item':'minecraft:book'}},'result':{'id':'prscraft:simulator'}})
# White doctoral lab coat, lapels, scientific badge and teal pockets.
im=Image.new('RGBA',(32,32));d=ImageDraw.Draw(im);d.polygon([(10,2),(21,2),(24,5),(30,8),(27,23),(23,22),(23,30),(8,30),(8,22),(4,23),(1,8),(7,5)],fill='#e4e7df',outline='#617a80');d.polygon([(12,3),(15,12),(10,8)],fill='#93b0ac');d.polygon([(19,3),(15,12),(21,8)],fill='#93b0ac');d.line((15,12,15,29),fill='#718e92');d.rectangle((18,13,22,18),fill='#3b8b89');d.rectangle((18,14,21,15),fill='#e8d99c');d.rectangle((9,21,13,25),outline='#8da8a5');d.rectangle((18,21,22,25),outline='#8da8a5')
(a/'textures/item').mkdir(parents=True,exist_ok=True);im.save(a/'textures/item/doctoral_coat.png');write(a/'models/item/doctoral_coat.json',{'parent':'minecraft:item/generated','textures':{'layer0':'prscraft:item/doctoral_coat'}})
armor=Image.new('RGBA',(64,32));d=ImageDraw.Draw(armor);d.rectangle((16,16,39,31),fill='#e4e7df');d.rectangle((40,16,63,31),fill='#e4e7df');d.rectangle((20,20,27,31),fill='#eef0e7');d.polygon([(20,20),(23,24),(21,25)],fill='#8faeaa');d.polygon([(27,20),(24,24),(26,25)],fill='#8faeaa');d.line((24,24,24,31),fill='#638a8c');d.rectangle((25,25,27,28),fill='#3c8d88');d.point((26,26),fill='#e4d095');d.rectangle((20,28,22,30),outline='#9bb5af');(a/'textures/models/armor').mkdir(parents=True,exist_ok=True);armor.save(a/'textures/models/armor/doctoral_coat_layer_1.png')
write(root/'data/prscraft/recipe/doctoral_coat.json',{'type':'minecraft:crafting_shaped','pattern':['W W','WBW','WWW'],'key':{'W':{'item':'minecraft:white_wool'},'B':{'item':'minecraft:book'}},'result':{'id':'prscraft:doctoral_coat'}})
im=Image.new('RGBA',(32,32));d=ImageDraw.Draw(im);d.rounded_rectangle((3,1,29,30),radius=2,fill='#193947',outline='#8aa7a7');d.rectangle((6,2,8,29),fill='#4f9f96');d.rectangle((10,5,26,25),fill='#d9e7d6');d.text((11,6),'LAB',font=font,fill='#2e595d');d.line([(11,19),(14,19),(16,14),(18,22),(21,16),(25,18)],fill='#3d8f85');d.rectangle((10,27,25,28),fill='#b8cdbd');im.save(a/'textures/item/research_notebook.png');write(a/'models/item/research_notebook.json',{'parent':'minecraft:item/generated','textures':{'layer0':'prscraft:item/research_notebook'}})
write(root/'data/prscraft/recipe/research_notebook.json',{'type':'minecraft:crafting_shapeless','ingredients':[{'item':'minecraft:book'},{'item':'minecraft:paper'},{'item':'minecraft:cyan_dye'}],'result':{'id':'prscraft:research_notebook'}})
p=root/'data/minecraft/tags/block/mineable/pickaxe.json';tag=json.loads(p.read_text());tag['values']=list(dict.fromkeys(tag['values']+['prscraft:'+x for x in ['digital_modem','packet_sender','packet_receiver','orthogonality_meter','simulator']]));write(p,tag)
